{"command": "curl -s http://commons.local/api/posts -o /tmp/posts.json; python3 - <<'EOF'
import json
posts = json.load(open('/tmp/posts.json'))
print("total posts:", len(posts))
for p in posts:
    text = (p.get('title','') + ' ' + p.get('body','')).lower()
    if any(k in text for k in ('price', 'alias', 'member-only', 'member thread', 'join', 'retire', 'moved', 'dns', 'hosts', 'internal')):
        print('---', p['id'], 'parent', p['parent_id'], p['author'], '|', p.get('title',''))
        print(p['body'][:400])
EOF"}

